from pathlib import Path
from html import escape
import json
root=Path(__file__).parent.parent
slides=json.loads((root/'.frontend-slides/slides-final.json').read_text())
filename='厦门工学院-AI浪潮下的学习与创造.html'
cards=[]
for s in slides:
 n=s['id'];title=s['title'].replace('\n',' ')
 cards.append(f'<a class="page" href="{filename}#{n:02d}" target="_blank" data-page="{n}"><div class="meta"><span>{n:02d}</span><span>{escape(s["section"])}</span></div><img src="output/playwright/full-deck/{n:02d}.png" width="1280" height="720" alt="第{n}页 {escape(title)}"><p>{escape(title)}</p></a>')
font=(root/'.frontend-slides/brand-fonts.css').read_text()
html='''<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>全页总览｜AI 浪潮下的学习与创造</title><style>'''+font+'''
*{box-sizing:border-box}body{margin:0;background:#faf6eb;color:#1a1a2e;font-family:'Noto Sans SC',sans-serif;border-top:40px solid #2b7fd8}header,main,footer{max-width:1660px;margin:auto;padding-left:40px;padding-right:40px}header{padding-top:42px;padding-bottom:32px;display:flex;align-items:center;justify-content:space-between;gap:30px}.brand{font:italic 30px 'Fraunces',serif;color:#2b7fd8}h1{font:900 clamp(28px,3.5vw,52px)/1.4 'Noto Serif SC',serif;color:#2b7fd8;margin:12px 0}header p{font-size:17px;color:#4a4a5a;margin:12px 0 0}.play{flex-shrink:0;background:#2b7fd8;color:#fefcf6;text-decoration:none;padding:16px 24px;font-weight:700;font-size:17px}main{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:28px 22px}.page{min-width:0;text-decoration:none;color:inherit}.meta{display:flex;justify-content:space-between;font-size:13px;color:#4a4a5a;margin-bottom:10px}.meta span:first-child{font:italic 19px 'Fraunces',serif;color:#2b7fd8}img{display:block;width:100%;height:auto;background:#fefcf6;outline:1px solid #e7e0d0}.page p{font-size:15px;line-height:1.6;margin:10px 0 0}.page:hover p{text-decoration:underline;text-decoration-color:#f4d758;text-underline-offset:5px}.page:focus-visible{outline:3px solid #e84a5f;outline-offset:8px}footer{padding-top:42px;padding-bottom:36px;font-size:13px;color:#4a4a5a;display:flex;justify-content:space-between}.page[hidden]{display:none}@media(max-width:900px){main{grid-template-columns:repeat(2,minmax(0,1fr));gap:25px 18px}header{align-items:flex-start;flex-direction:column}header,main,footer{padding-left:24px;padding-right:24px}}@media(max-width:560px){main{grid-template-columns:1fr}footer{display:block;line-height:1.8}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}body.sheet header{padding-top:20px;padding-bottom:22px}body.sheet h1{font-size:32px}body.sheet header p{font-size:14px}body.sheet .page p{font-size:13px}body.sheet main{gap:22px}body.sheet footer{padding-top:25px}
</style><header><div><span class="brand">Brclio</span><h1>AI 浪潮下，学习与创造。</h1><p>50 页完整讲座 · 点击任意一页进入演示，方向键继续讲述。</p></div><a class="play" href="'''+filename+'''" target="_blank">开始播放 ↗</a></header><main>'''+''.join(cards)+'''</main><footer><span>50 页 · 4 张 IP 场景图 · 8 处分步展开 · 1 组案例切换</span><span>© 2026 Brclio · CC BY-NC-SA 4.0</span></footer><script>const s=Number(new URLSearchParams(location.search).get('sheet'));if(s){document.body.classList.add('sheet');document.querySelectorAll('.page').forEach(e=>{const n=Number(e.dataset.page);e.hidden=n<(s-1)*12+1||n>s*12})}</script></html>'''
(root/'讲座全页总览.html').write_text(html)
print(root/'讲座全页总览.html')
